// Forge repair: scope both initial RSX discovery and notify registration to actual
// crate roots, pruning ignored directories before descent. Never follow symlinks.
fn scoped_watch_entries(workspace: &Workspace, crate_dir: &Path) -> impl Iterator<Item = (PathBuf, bool)> {
    let mut builder = ignore::gitignore::GitignoreBuilder::new(crate_dir);
    for pattern in Workspace::default_ignore_list() {
        builder.add_line(None, pattern).expect("invalid default watch ignore");
    }
    builder.add(workspace.workspace_root().join(".gitignore"));
    builder.add(crate_dir.join(".gitignore"));
    let ignore = builder.build().expect("invalid crate watch ignore");
    let root = crate_dir.to_path_buf();
    let mut pending = vec![root.clone()];
    std::iter::from_fn(move || loop {
        let path = pending.pop()?;
        let Ok(metadata) = std::fs::symlink_metadata(&path) else { continue; };
        if metadata.file_type().is_symlink()
            || (path != root && ignore.matched(&path, metadata.is_dir()).is_ignore())
        {
            continue;
        }
        if metadata.is_dir() {
            if let Ok(entries) = std::fs::read_dir(&path) {
                pending.extend(entries.flatten().map(|entry| entry.path()));
            }
        }
        return Some((path, metadata.is_dir()));
    })
}

